// Determines how many unique/boss monsters to spawn for pMonterRegion in pRoom. If current unique count is below nBossMin and the room density roll (spawned/total rooms) passes, returns 0 (skip). If below nBossMax and a 6% roll passes, returns 0. Otherwise returns 1 (spawn normal) or 2 (spawn extra) based on a 35% random threshold using the room seed.
int32_t __fastcall MONSTERREGION_CheckSpawnDensity(D2MonsterRegionStrc * pMonterRegion, D2RoomStrc * pRoom) {
    D2SeedStrc* pSeed;
    int nTotalLevelRooms;
    D2SeedStrc sNextSeed;
    uint8_t byUniqueCount = pMonterRegion->nBossMax;
    uint8_t byCurUniqueCount = (uint8_t)pMonterRegion->dwUniqueCount;
    if (byCurUniqueCount < pMonterRegion->nBossMin) {
      int nSpawnedRooms;
      nTotalLevelRooms = pMonterRegion->nLevelRoomsCount;
      if (nTotalLevelRooms) {
        nSpawnedRooms = pMonterRegion->nRoomsCount;
        if (pRoom) {
          pSeed = &pRoom->sSeed;
        } else {
          pSeed = 0;
        }

        sNextSeed = D2_SEED_NEXT(*pSeed);
        *pSeed = sNextSeed;
        if ((int)(sNextSeed.nSeedLow % 100) < nSpawnedRooms * 100 / nTotalLevelRooms) {
          return 0;
        }
      }
    }
    if (byCurUniqueCount < byUniqueCount) {
      if (pRoom) {
        pSeed = &pRoom->sSeed;
      } else {
        pSeed = 0;
      }

      sNextSeed = D2_SEED_NEXT(*pSeed);
      *pSeed = sNextSeed;
      if ((int)(sNextSeed.nSeedLow % 100) <= 5) {
        return 0;
      }
    }
    if (pRoom) {
      pSeed = &pRoom->sSeed;
    } else {
      pSeed = 0;
    }

    sNextSeed = D2_SEED_NEXT(*pSeed);
    *pSeed = sNextSeed;
    return ((int)(sNextSeed.nSeedLow % 100) > 0x23) + 1;
}

// @sourcefile .\SKILLS\SkillItem.cpp
BOOL __fastcall SKILLITEM_ItemSpellInit_UseStackable(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pItem, D2UnitStrc * pTarget, int nX, int nY, eD2Skills eSkill) {
    D2Common::ITEMS::Items::ITEM_EditItemData_eItemFlag(pItem, ITEMFLAG_CURSOR, 1);
    int nSpellIcon = D2Common::ITEMS::Items::ITEM_GetSpellIcon(pItem);
    if (nSpellIcon < 0) {
      return 1;
    }

    GAME::SCmd::NET_D2GS_SERVER_Send_0x3F_SETSPELLICON(UNIT::SUnit::SUNIT_GetClient(pUnit, ".\\SKILLS\\SkillItem.cpp", 0x40), pItem, (uint8_t)nSpellIcon, 0, 1, (uint16_t)eSkill);
    return 1;
}

static D2InventoryStrc * SKILLITEM_FindItemInInventory(D2UnitStrc * pUnit, D2UnitStrc * nParam) {
    if (!nParam->pInventory) {
      return nullptr;
    }

    D2UnitStrc* pCursorItem_lcl = D2Common::INVENTORY::Inventory::INVENTORY_GetFirstItem(nParam->pInventory);
    while (true) {
      D2UnitStrc* pFoundItem;
      if (!pCursorItem_lcl) {
        return nullptr;
      }

      pFoundItem = D2Common::INVENTORY::Inventory::GetCarriedItem(pCursorItem_lcl);
      if (pFoundItem == pUnit) {
        break;
      }

      pCursorItem_lcl = D2Common::INVENTORY::Inventory::INVENTORY_GetNextItem(pCursorItem_lcl);
    }

    return (D2InventoryStrc*)0x1;
}

// @sourcefile .\SKILLS\SkillItem.cpp
static void SKILLITEM_ClearCursorFlagAndNotifyClient(D2UnitStrc * pUnit) {
    D2UnitStrc* pUnitTmp;
    BOOL bHasCursorFlag;
    uint8_t nItemSlot;
    int32_t nParam;
    uint16_t nSkillId;
    if (!pUnit->pInventory) {
      return;
    }

    for (pUnitTmp = D2Common::INVENTORY::Inventory::INVENTORY_GetFirstItem(pUnit->pInventory); pUnitTmp; pUnitTmp = D2Common::INVENTORY::Inventory::INVENTORY_GetNextItem(pUnitTmp)) {
      D2UnitStrc* pUnitTmp2;
      pUnitTmp2 = D2Common::INVENTORY::Inventory::GetCarriedItem(pUnitTmp);
      bHasCursorFlag = D2Common::ITEMS::Items::CheckItemFlag(pUnitTmp2, ITEMFLAG_CURSOR, 0x77, ".\\SKILLS\\SkillItem.cpp");
      if (bHasCursorFlag) {
        D2Common::ITEMS::Items::ITEM_EditItemData_eItemFlag(pUnitTmp2, ITEMFLAG_CURSOR, 0);
        nSkillId = 0xffff;
        nParam = 0;
        bHasCursorFlag = 1;
        nItemSlot = 0xff;
        GAME::SCmd::NET_D2GS_SERVER_Send_0x3F_SETSPELLICON(UNIT::SUnit::SUNIT_GetClient(pUnit, ".\\SKILLS\\SkillItem.cpp", 0x7a), pUnitTmp2, nItemSlot, bHasCursorFlag, nParam, nSkillId);
      }
    }
}

// @sourcefile .\SKILLS\SkillItem.cpp
BOOL __fastcall SKILLITEM_IdentifyScrollSpell(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pItem, D2UnitStrc * pTarget, int nX, int nY, eD2Skills eSkill) {
    BOOL bIsTrading = PLAYER::PlayerTrade::IsInteractingWithPlayer(pGame, pUnit, 1);
    if (bIsTrading) {
      return 0;
    }

    BOOL bIsIdentified = D2Common::ITEMS::Items::CheckItemFlag(pTarget, ITEMFLAG_IDENTIFIED, 0x93, ".\\SKILLS\\SkillItem.cpp");
    if (bIsIdentified) {
      return 0;
    }

    D2InventoryStrc* pInventoryResult = SKILLITEM_FindItemInInventory(pTarget, pUnit);
    if (!pInventoryResult) {
      return 0;
    }

    ITEMS::ItemMode::ITEMMODE_ProcessItemSell(pGame, pUnit, pTarget);
    return 1;
}

// Server handler for the Town Portal scroll spell (player units only). If the caster is in town or Uber Tristram, plays the fail sound and returns 0. Otherwise destroys any existing portal pair, spawns a new Town Portal object (obj 0x3B) at the caster's position via SERVER_SpawnPortal, records the portal GUID on the player, rebinds any previous portal owner, fires quest callbacks, and sends CMD 0x7C to the client. Returns 1 on successful portal creation.
// @sourcefile .\SKILLS\SkillItem.cpp
BOOL __fastcall SKILLITEM_TownPortalScrollSpell(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pItem, D2UnitStrc * pTarget, int nX, int nY, eD2Skills eSkill) {
    eAct nAct;
    D2RoomStrc* pRoom;
    eD2LevelId eLevelId;
    BOOL bInTown;
    D2UnitStrc* pPrevPortalOwner;
    uint32_t nPortalGUID;
    D2UnitStrc* pNewPortal;
    uint8_t byItemUnitType;
    int nItemGUID;
    int32_t nPortalObjId;
    D2UnitStrc** ppNewPortal;
    if ((pUnit ? pUnit->eUnitType : ~UNIT_PLAYER) != UNIT_PLAYER) {
      return 0;
    }

    pUnit->eUnitFlags |= UNITFLAG_SKSRVDOFUNC;
    pRoom = D2Common::Units::UNITS_GetRoom(pUnit);
    eLevelId = D2Common::DUNGEON::Dungeon::DRLGROOM_GetLevelIdFromRoom(pRoom);
    nAct = D2Common::Drlg::GetActNoFromLevelNumber(eLevelId);
    eLevelId = D2Common::DUNGEON::Dungeon::GetTownLevelIdFromActNo(nAct);
    bInTown = D2Common::DUNGEON::Dungeon::DRLGROOM_IsRoomInTown(pRoom);
    if (!bInTown) {
      eD2LevelId eLevelId2;
      eLevelId2 = D2Common::DUNGEON::Dungeon::DRLGROOM_GetLevelIdFromRoom(pRoom);
      if (eLevelId2 != LEVEL_UberTristram) {
        PLAYER::Player::PLAYER_DestroyPortalPair(pGame, pUnit);
        bInTown = 0;
        nPortalObjId = 0x3b;
        ppNewPortal = &pNewPortal;
        pNewPortal = 0;
        bInTown = SkillsServer::SERVER_SpawnPortal(pGame, pUnit, pRoom, D2Client::Units::GetXPosFromDynamicPathUnit(pUnit), D2Client::Units::GetYPosFromDynamicPathUnit(pUnit), eLevelId, ppNewPortal, nPortalObjId, bInTown);
        UNIT::SUnit::SetupUpdateEvent_AttachEventSound(pUnit, UNITEVENTCALLBACK_MONUMOD, nullptr);
        if (bInTown) {
          if (!pNewPortal) {
            nPortalGUID = -1;
          } else {
            nPortalGUID = pNewPortal->nUnitGUID;
          }

          PLAYER::Player::PLAYER_SetUniqueId(pUnit, nPortalGUID);
          if (pNewPortal) {
            Objects::OBJECTS_SetUnitIdInTimerArg(pNewPortal, pUnit->nUnitGUID);
            pPrevPortalOwner = UNIT::SUnit::UNITS_FindPortalOwnerUnit(pGame, pNewPortal);
            if (pPrevPortalOwner) {
              Objects::OBJECTS_SetUnitIdInTimerArg(pPrevPortalOwner, pUnit->nUnitGUID);
              Quests::QUESTS::A5Q5::Q35_OnPlayerDeath(pGame, pPrevPortalOwner);
            }

            Quests::QUESTS::A5Q5::Q35_OnPlayerDeath(pGame, pNewPortal);
          }
        }
        if (!pItem) {
          return bInTown;
        }

        nItemGUID = pItem->nUnitGUID;
        byItemUnitType = (uint8_t)pItem->eUnitType;
        GAME::SCmd::NET_D2GS_SERVER_Send_CMD_BYTE_INT(UNIT::SUnit::SUNIT_GetClient(pUnit, ".\\SKILLS\\SkillItem.cpp", 0xda), 0x7c, byItemUnitType, nItemGUID);
        return bInTown;
      }
    }

    UNIT::SUnit::SetupUpdateEvent_AttachEventSound(pUnit, 0x18, pUnit);
    return 0;
}

// Applies a consumed potion/consumable item's effects to pUnit. Looks up the item's ItemsTxt line, computes the effect duration (ITEMS_SearchItemCodeTable) and its state, then iterates the item's up-to-3 stat columns: each stat value is difficulty-scaled (potion value/regen), optionally doubled by a random crit roll vs the relevant attribute, and value-shifted. Instant stats (hp/mana) are added directly (capped at maxstat, with blood-golem leech for life); over-time stats are blended into a state-backed timed stat list (allocating/attaching one and scheduling regen/expire events). If HP changed on a player it sends the 0xAB hp-percent update when the delta exceeds 4. pItem is the consumed item unit (its +4 nClassId selects the ItemsTxt row).
BOOL __fastcall ITEM_ApplyConsumableEffects(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pItem, D2UnitStrc * pTarget, int nX, int nY, eD2Skills eSkill) {
    uint32_t nItemClassId;
    D2ItemStatCostTxt* pStatCost;
    uint32_t nStatValue;
    uint32_t nAttribVal;
    uint32_t nRandRoll;
    int nPotionDelay;
    int32_t nOwnerGUID;
    eD2UnitType eUnitType;
    int nCurStatVal;
    eD2UnitStat eUnitStat;
    int nStatScaled;
    int iStatEntry;
    eD2UnitStat eMaxStatId;
    if (!pItem) {
      nItemClassId = -1;
    } else {
      nItemClassId = pItem->nClassId;
    }

    D2ItemsTxt* pItemTxt;
    pItemTxt = D2Common::DATATBLS::ItemTbls::TXT_Items_GetLine(nItemClassId);
    if (!pItemTxt) {
      return 0;
    }

    nItemClassId = D2Common::ITEMS::Items::ITEMS_SearchItemCodeTable(pUnit, (int32_t)pItem, pItemTxt->dwLen);
    eD2States eState;
    eState = (eD2States)pItemTxt->wState;
    D2StatListExStrc* pActiveStatList;
    pActiveStatList = 0;
    int nBuffRemainingFrames;
    nBuffRemainingFrames = 0;
    if ((int)nItemClassId > 0) {
      if ((int)eState <= 0) {
        return 0;
      }
      if ((int)eState >= sgptDataTable->nTxtStatesSize) {
        return 0;
      }

      pActiveStatList = D2Common::Stats::StatsEx::GetStatsByState(pUnit, eState);
      if (pActiveStatList) {
        nBuffRemainingFrames = D2Common::Stats::StatsEx::STATLIST_GetFullListPtr(pActiveStatList);
        nBuffRemainingFrames -= pGame->dwGameFrame;
      }
    }

    BOOL bApplied;
    bApplied = 0;
    bool bHpModified;
    bHpModified = false;
    for (iStatEntry = 0; iStatEntry < 3; iStatEntry++) {
      eUnitStat = (eD2UnitStat)*(short int*)(pItemTxt->szSetInvFile + iStatEntry * 2 + 0x3e);
      if ((int)eUnitStat < 0 || (int)eUnitStat >= sgptDataTable->nTxtItemStatCostSize) {
        break;
      }

      pStatCost = sgptDataTable->pTxtItemStatCost + eUnitStat;
      if (pStatCost) {
        nStatValue = D2Common::ITEMS::Items::ITEMS_SearchItemCodeTable(pUnit, (int32_t)pItem, *(uint32_t*)(pItemTxt->szSetInvFile + iStatEntry * 4 + 0x44));
        switch (eUnitStat) {
          default:
            goto apply_stat_value;
          case UNITSTAT_manarecovery:
            nStatValue <<= 8;
          case UNITSTAT_mana:
            nStatValue = D2Common::ITEMS::Items::ITEMS_ModifyPotionSellValueByDifficulty(pUnit, nStatValue);
          eMaxStatId = UNITSTAT_energy;
          break;
          case UNITSTAT_hpregen:
            nStatValue <<= 8;
          case UNITSTAT_hitpoints:
            nStatValue = D2Common::ITEMS::Items::ITEMS_ModifyPotionValueByDifficulty(pUnit, nStatValue);
          eMaxStatId = UNITSTAT_vitality;
        }

        nAttribVal = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, eMaxStatId, 0);
        if ((int)nAttribVal > 0) {
          nAttribVal = D2Client::Archive::RANDOM_RandomNumberSelector(&pUnit->sSeed, nAttribVal);
          nRandRoll = D2Client::Archive::UNIT_GetModuloFromSeed(&pUnit->sSeed, 100);
          if ((int)nRandRoll < (int)(nAttribVal >> 1)) {
            nStatValue *= 2;
          }
        }

        apply_stat_value:
        nStatScaled = nStatValue << (pStatCost->valshift & 0x1fU);
        if (nStatScaled > 0) {
          if (eUnitStat != UNITSTAT_hitpoints) {
            if (eUnitStat == UNITSTAT_hpregen) {
              eUnitType = D2Client::Units::GetType(pUnit);
              if (eUnitType == UNIT_PLAYER) {
                nStatScaled = SkillNec::BloodGolemLifeLeech(pGame, pUnit, nStatScaled);
              }
            }
          } else {
            bHpModified = true;
            eUnitType = D2Client::Units::GetType(pUnit);
            if (eUnitType == UNIT_PLAYER) {
              nStatScaled = SkillNec::BloodGolemLifeLeech(pGame, pUnit, nStatScaled);
            }
          }
          if ((int)nItemClassId <= 0) {
            nPotionDelay = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, eUnitStat, 0);
            if ((int)(uint32_t)(uint16_t)pStatCost->maxstat < sgptDataTable->nTxtItemStatCostSize) {
              nCurStatVal = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, (eD2UnitStat)(uint16_t)pStatCost->maxstat, 0);
              if (nPotionDelay + nStatScaled > nCurStatVal) {
                nStatScaled = nCurStatVal - nPotionDelay;
              }
            }

            D2Common::Stats::StatsEx::STATLIST_AddUnitStat(pUnit, eUnitStat, nStatScaled, 0);
          } else {
            nPotionDelay = pGame->dwGameFrame + nBuffRemainingFrames + nItemClassId;
            if (!pActiveStatList) {
              nOwnerGUID = D2Client::UNIT::GetGUID(pUnit);
              eUnitType = D2Client::Units::GetType(pUnit);
              pActiveStatList = (D2StatListExStrc*)D2Common::Stats::StatsEx::AllocStatList(pGame->pMemoryPool, 2, nPotionDelay, eUnitType, nOwnerGUID);
              if (!pActiveStatList) {
                continue;
              }

              D2Common::Stats::StatsEx::SetState(pActiveStatList, eState);
              D2Common::DATATBLS::ItemStats::SetState(pUnit, eState, 1);
              eUnitType = D2Client::Units::GetType(pUnit);
              if (eUnitType != UNIT_PLAYER) {
                GAME::Event::EVENT_RemoveUnitTimersByType(pGame, pUnit, UNITEVENTCALLBACK_STATREGEN, 0);
                GAME::Event::SetEvent(pGame, pUnit, 3, pGame->dwGameFrame + 1, 0, 0);
              }

              D2Common::Stats::StatsEx::STATLIST_SetExpireFunction(pActiveStatList, SkillsServer::DefaultExpireFunction);
              D2Common::Stats::StatsEx::STATLIST_AttachStatListToUnit(pUnit, pActiveStatList, 1);
            }

            D2Common::Stats::StatsEx::STATSEX_SetStatListTimeout(pActiveStatList, nPotionDelay);
            nCurStatVal = D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue(pActiveStatList, eUnitStat, 0);
            if (!iStatEntry) {
              GAME::Event::SetEvent(pGame, pUnit, 0xc, nPotionDelay, 0, 0);
            }
            if ((int)(nItemClassId + nBuffRemainingFrames) > 0) {
              D2Common::Stats::StatsEx::D2AddStatToStatsListEx(pActiveStatList, eUnitStat, (nCurStatVal * nBuffRemainingFrames + nStatScaled) / (int)(nItemClassId + nBuffRemainingFrames), 0);
            }
          }

          bApplied = 1;
        }
      }
    }

    if (!(bHpModified && pUnit && pUnit->eUnitType == UNIT_PLAYER)) {
      return bApplied;
    }

    uint32_t nPrevHpPct = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_last_sent_hp_pct, 0);
    uint8_t bParam = PLAYER::PlayerModes::PLRMODES_GetHpPercent128(pUnit);
    nStatScaled = (nPrevHpPct & 0xff) - (uint32_t)bParam;
    if (nStatScaled < 0) {
      nStatScaled = -nStatScaled;
    }
    if (nStatScaled <= 4) {
      return bApplied;
    }

    UNIT::SUnitMsg::UnitQueuePacket0xAB(pUnit, bParam);
    D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit, UNITSTAT_last_sent_hp_pct, (uint32_t)bParam, 0);
    return bApplied;
}

// Applies a consumable/charm item's regen-and-stat effects to a unit. Reads the item's ItemsTxt (state + up to 3 stat entries), scales each value by valshift (mana/hp regen pre-shifted by 8), and either adds the stat instantly (clamped to its maxstat) or, for timed buffs, allocates/refreshes a state stat-list on the unit averaging the new value with any remaining buff. Player hitpoint/hpregen gains route through BloodGolemLifeLeech; on hp change for players, sends a 0xAB hp-percent update packet. Server-side. Returns bApplied: TRUE if any stat was applied (EAX from [EBP-0x1c] at 005beaa6).
BOOL __fastcall ITEM_ApplyConsumableEffectsSimple(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pItem, D2UnitStrc * pTarget, int nX, int nY, eD2Skills eSkill) {
    uint32_t nItemClassId;
    uint32_t nStatValue;
    int nCurStatVal;
    int32_t nOwnerGUID;
    eD2UnitType eUnitType;
    int nCurrentStatVal;
    eD2UnitStat eUnitStat;
    int iStatEntry;
    int nStatScaled;
    if (!pItem) {
      nItemClassId = -1;
    } else {
      nItemClassId = pItem->nClassId;
    }

    D2ItemsTxt* pItemTxt = D2Common::DATATBLS::ItemTbls::TXT_Items_GetLine(nItemClassId);
    if (!pItemTxt) {
      return 0;
    }

    nItemClassId = D2Common::ITEMS::Items::ITEMS_SearchItemCodeTable(pUnit, (int32_t)pItem, pItemTxt->dwLen);
    eD2States eState = (eD2States)pItemTxt->wState;
    D2StatListExStrc* pActiveStatList = 0;
    int nBuffRemainingFrames = 0;
    if ((int)nItemClassId > 0) {
      if ((int)eState <= 0) {
        return 0;
      }
      if ((int)eState >= sgptDataTable->nTxtStatesSize) {
        return 0;
      }

      pActiveStatList = D2Common::Stats::StatsEx::GetStatsByState(pUnit, eState);
      if (pActiveStatList) {
        nBuffRemainingFrames = D2Common::Stats::StatsEx::STATLIST_GetFullListPtr(pActiveStatList);
        nBuffRemainingFrames -= pGame->dwGameFrame;
      }
    }

    BOOL bApplied = 0;
    bool bHpModified = false;
    for (iStatEntry = 0; iStatEntry < 3; iStatEntry++) {
      D2ItemStatCostTxt* pStatCost;
      eUnitStat = (eD2UnitStat)*(short int*)(pItemTxt->szSetInvFile + iStatEntry * 2 + 0x3e);
      if ((int)eUnitStat < 0 || (int)eUnitStat >= sgptDataTable->nTxtItemStatCostSize) {
        break;
      }

      pStatCost = sgptDataTable->pTxtItemStatCost + eUnitStat;
      if (pStatCost) {
        nStatValue = D2Common::ITEMS::Items::ITEMS_SearchItemCodeTable(pUnit, (int32_t)pItem, *(uint32_t*)(pItemTxt->szSetInvFile + iStatEntry * 4 + 0x44));
        if (eUnitStat == UNITSTAT_manarecovery || eUnitStat == UNITSTAT_hpregen) {
          nStatValue <<= 8;
        }

        nStatScaled = nStatValue << (pStatCost->valshift & 0x1fU);
        if (nStatScaled > 0) {
          if (eUnitStat != UNITSTAT_hitpoints) {
            if (eUnitStat == UNITSTAT_hpregen) {
              eUnitType = D2Client::Units::GetType(pUnit);
              if (eUnitType == UNIT_PLAYER) {
                nStatScaled = SkillNec::BloodGolemLifeLeech(pGame, pUnit, nStatScaled);
              }
            }
          } else {
            bHpModified = true;
            eUnitType = D2Client::Units::GetType(pUnit);
            if (eUnitType == UNIT_PLAYER) {
              nStatScaled = SkillNec::BloodGolemLifeLeech(pGame, pUnit, nStatScaled);
            }
          }
          if ((int)nItemClassId <= 0) {
            nCurStatVal = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, eUnitStat, 0);
            if ((int)(uint32_t)(uint16_t)pStatCost->maxstat < sgptDataTable->nTxtItemStatCostSize) {
              nCurrentStatVal = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, (eD2UnitStat)(uint16_t)pStatCost->maxstat, 0);
              if (nCurStatVal + nStatScaled > nCurrentStatVal) {
                nStatScaled = nCurrentStatVal - nCurStatVal;
              }
            }

            D2Common::Stats::StatsEx::STATLIST_AddUnitStat(pUnit, eUnitStat, nStatScaled, 0);
          } else {
            nCurStatVal = pGame->dwGameFrame + nBuffRemainingFrames + nItemClassId;
            if (!pActiveStatList) {
              nOwnerGUID = D2Client::UNIT::GetGUID(pUnit);
              eUnitType = D2Client::Units::GetType(pUnit);
              pActiveStatList = (D2StatListExStrc*)D2Common::Stats::StatsEx::AllocStatList(pGame->pMemoryPool, 2, nCurStatVal, eUnitType, nOwnerGUID);
              if (!pActiveStatList) {
                continue;
              }

              D2Common::Stats::StatsEx::SetState(pActiveStatList, eState);
              D2Common::DATATBLS::ItemStats::SetState(pUnit, eState, 1);
              eUnitType = D2Client::Units::GetType(pUnit);
              if (eUnitType != UNIT_PLAYER) {
                GAME::Event::EVENT_RemoveUnitTimersByType(pGame, pUnit, UNITEVENTCALLBACK_STATREGEN, 0);
                GAME::Event::SetEvent(pGame, pUnit, 3, pGame->dwGameFrame + 1, 0, 0);
              }

              D2Common::Stats::StatsEx::STATLIST_SetExpireFunction(pActiveStatList, SkillsServer::DefaultExpireFunction);
              D2Common::Stats::StatsEx::STATLIST_AttachStatListToUnit(pUnit, pActiveStatList, 1);
            }

            D2Common::Stats::StatsEx::STATSEX_SetStatListTimeout(pActiveStatList, nCurStatVal);
            nCurrentStatVal = D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue(pActiveStatList, eUnitStat, 0);
            if (!iStatEntry) {
              GAME::Event::SetEvent(pGame, pUnit, 0xc, nCurStatVal, 0, 0);
            }
            if ((int)(nItemClassId + nBuffRemainingFrames) > 0) {
              D2Common::Stats::StatsEx::D2AddStatToStatsListEx(pActiveStatList, eUnitStat, (nCurrentStatVal * nBuffRemainingFrames + nStatScaled) / (int)(nItemClassId + nBuffRemainingFrames), 0);
            }
          }

          bApplied = 1;
        }
      }
    }

    if (!(bHpModified && pUnit && pUnit->eUnitType == UNIT_PLAYER)) {
      return bApplied;
    }

    uint32_t nPrevHpPct = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_last_sent_hp_pct, 0);
    uint8_t bParam = PLAYER::PlayerModes::PLRMODES_GetHpPercent128(pUnit);
    nCurStatVal = (nPrevHpPct & 0xff) - (uint32_t)bParam;
    if (nCurStatVal < 0) {
      nCurStatVal = -nCurStatVal;
    }
    if (nCurStatVal <= 4) {
      return bApplied;
    }

    UNIT::SUnitMsg::UnitQueuePacket0xAB(pUnit, bParam);
    D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit, UNITSTAT_last_sent_hp_pct, (uint32_t)bParam, 0);
    return bApplied;
}

// Item-skill handler that restores a percentage of capped stats (e.g. healing/mana/rejuvenation potions). Looks up the item's ItemsTxt row, reads its state (wState) and a duration via ITEMS_SearchItemCodeTable. Iterates up to 3 stat slots encoded in the item's szCode block: for each, scales the stat's max value by a percent (D2ApplyPercent), applies BloodGolemLifeLeech adjustment when restoring HP/HP-regen on a player. If duration<=0 the restore is instant (STATLIST_AddUnitStat, clamped to max). If duration>0 it instead attaches/refreshes a timed state-list, blending the buffed amount over remaining frames and registering regen timer events. After processing all slots, if HP was modified on a player it sends the new HP-percent (UnitQueuePacket 0xAB) and updates UNITSTAT_last_sent_hp_pct. Returns bApplied: TRUE if any stat was applied (EAX from [EBP-0x24] at 005bed90).
BOOL __fastcall ITEM_ApplyPercentRestoration(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pItem, D2UnitStrc * pTarget, int nX, int nY, eD2Skills eSkill) {
    uint32_t nItemDuration;
    uint32_t nPercent;
    int nCurStatVal;
    int32_t nOwnerGUID;
    eD2UnitType eUnitType;
    int pExpireFrame;
    D2ItemStatCostTxt* pStatCost;
    int iStatSlot;
    int32_t nStatScaled;
    if (!pItem) {
      nItemDuration = -1;
    } else {
      nItemDuration = pItem->nClassId;
    }

    D2ItemsTxt* pItemTxt = D2Common::DATATBLS::ItemTbls::TXT_Items_GetLine(nItemDuration);
    if (!pItemTxt) {
      return 0;
    }

    nItemDuration = D2Common::ITEMS::Items::ITEMS_SearchItemCodeTable(pUnit, (int32_t)pItem, pItemTxt->dwLen);
    eD2States eState = (eD2States)pItemTxt->wState;
    D2StatListExStrc* pActiveStatList = 0;
    int nBuffRemainingFrames = 0;
    if ((int)nItemDuration > 0) {
      if ((int)eState <= 0) {
        return 0;
      }
      if ((int)eState >= sgptDataTable->nTxtStatesSize) {
        return 0;
      }

      pActiveStatList = D2Common::Stats::StatsEx::GetStatsByState(pUnit, eState);
      if (pActiveStatList) {
        nBuffRemainingFrames = D2Common::Stats::StatsEx::STATLIST_GetFullListPtr(pActiveStatList);
        nBuffRemainingFrames -= pGame->dwGameFrame;
      }
    }

    BOOL bApplied = 0;
    bool bHpModified = false;
    for (iStatSlot = 0; iStatSlot < 3; iStatSlot++) {
      eD2UnitStat eUnitStat;
      eUnitStat = (eD2UnitStat)*(short int*)(pItemTxt->szSetInvFile + iStatSlot * 2 + 0x3e);
      if ((int)eUnitStat >= 0 && (int)eUnitStat < sgptDataTable->nTxtItemStatCostSize) {
        pStatCost = sgptDataTable->pTxtItemStatCost + eUnitStat;
        if (pStatCost && (int)(uint32_t)(uint16_t)pStatCost->maxstat < sgptDataTable->nTxtItemStatCostSize) {
          nPercent = D2Common::ITEMS::Items::ITEMS_SearchItemCodeTable(pUnit, (int32_t)pItem, *(uint32_t*)(pItemTxt->szSetInvFile + iStatSlot * 4 + 0x44));
          if ((int)nPercent > 0) {
            pExpireFrame = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, (eD2UnitStat)(uint16_t)pStatCost->maxstat, 0);
            nStatScaled = D2Client::Stats::D2ApplyPercent(pExpireFrame, nPercent, 100);
            if (nPercent == 100) {
              nStatScaled = pExpireFrame;
            }
            if (eUnitStat != UNITSTAT_hitpoints) {
              if (eUnitStat == UNITSTAT_hpregen) {
                eUnitType = D2Client::Units::GetType(pUnit);
                if (eUnitType == UNIT_PLAYER) {
                  nStatScaled = SkillNec::BloodGolemLifeLeech(pGame, pUnit, nStatScaled);
                }
              }
            } else {
              bHpModified = true;
              eUnitType = D2Client::Units::GetType(pUnit);
              if (eUnitType == UNIT_PLAYER) {
                nStatScaled = SkillNec::BloodGolemLifeLeech(pGame, pUnit, nStatScaled);
              }
            }
            if ((int)nItemDuration <= 0) {
              nCurStatVal = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, eUnitStat, 0);
              if (nCurStatVal + nStatScaled > pExpireFrame) {
                nStatScaled = pExpireFrame - nCurStatVal;
              }

              D2Common::Stats::StatsEx::STATLIST_AddUnitStat(pUnit, eUnitStat, nStatScaled, 0);
            } else {
              pExpireFrame = pGame->dwGameFrame + nBuffRemainingFrames + nItemDuration;
              if (!pActiveStatList) {
                nOwnerGUID = D2Client::UNIT::GetGUID(pUnit);
                eUnitType = D2Client::Units::GetType(pUnit);
                pActiveStatList = (D2StatListExStrc*)D2Common::Stats::StatsEx::AllocStatList(pGame->pMemoryPool, 2, pExpireFrame, eUnitType, nOwnerGUID);
                if (!pActiveStatList) {
                  continue;
                }

                D2Common::Stats::StatsEx::SetState(pActiveStatList, eState);
                D2Common::DATATBLS::ItemStats::SetState(pUnit, eState, 1);
                eUnitType = D2Client::Units::GetType(pUnit);
                if (eUnitType != UNIT_PLAYER) {
                  GAME::Event::EVENT_RemoveUnitTimersByType(pGame, pUnit, UNITEVENTCALLBACK_STATREGEN, 0);
                  GAME::Event::SetEvent(pGame, pUnit, 3, pGame->dwGameFrame + 1, 0, 0);
                }

                D2Common::Stats::StatsEx::STATLIST_SetExpireFunction(pActiveStatList, SkillsServer::DefaultExpireFunction);
                D2Common::Stats::StatsEx::STATLIST_AttachStatListToUnit(pUnit, pActiveStatList, 1);
              }

              D2Common::Stats::StatsEx::STATSEX_SetStatListTimeout(pActiveStatList, pExpireFrame);
              nCurStatVal = D2Common::Stats::StatsEx::STATLIST_GetBaseStatValue(pActiveStatList, eUnitStat, 0);
              if (!iStatSlot) {
                GAME::Event::SetEvent(pGame, pUnit, 0xc, pExpireFrame, 0, 0);
              }
              if ((int)(nBuffRemainingFrames + nItemDuration) > 0) {
                D2Common::Stats::StatsEx::D2AddStatToStatsListEx(pActiveStatList, eUnitStat, (nCurStatVal * nBuffRemainingFrames + nStatScaled) / (int)(nBuffRemainingFrames + nItemDuration), 0);
              }
            }

            bApplied = 1;
          }
        }
      }
    }

    if (!(bHpModified && pUnit && pUnit->eUnitType == UNIT_PLAYER)) {
      return bApplied;
    }

    uint8_t bParam = PLAYER::PlayerModes::PLRMODES_GetHpPercent128(pUnit);
    UNIT::SUnitMsg::UnitQueuePacket0xAB(pUnit, bParam);
    D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit, UNITSTAT_last_sent_hp_pct, (uint32_t)bParam, 0);
    return bApplied;
}

// Applies timed buff stats from a consumable item (e.g. potions with duration) to pUnit. Looks up the item's TXT row, validates the associated state, computes stacked duration (existing remaining frames + new duration), allocates or reuses a stat-list for the state, sets a game-event timer for expiry, then iterates the item's three stat/calc pairs adding each to the stat list. Handles stamina fill-to-max as a special case for UNITSTAT_staminarecoverybonus.
BOOL __fastcall ITEM_ApplyTimedBuffStats(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pItem, D2UnitStrc * pTarget, int nX, int nY, eD2Skills eSkill) {
    uint32_t nItemDuration;
    eD2UnitType eUnitType;
    D2ItemStatCostTxt* pStatCost;
    int nCurrentStamina;
    int32_t nUnitGUID;
    eD2UnitStat eUnitStat;
    if (!pItem) {
      nItemDuration = -1;
    } else {
      nItemDuration = pItem->nClassId;
    }

    D2ItemsTxt* pItemTxt = D2Common::DATATBLS::ItemTbls::TXT_Items_GetLine(nItemDuration);
    if (!pItemTxt) {
      return 0;
    }

    eD2States eState = (eD2States)pItemTxt->wState;
    if ((int)eState <= 0) {
      return 0;
    }
    if ((int)eState >= sgptDataTable->nTxtStatesSize) {
      return 0;
    }

    nItemDuration = D2Common::ITEMS::Items::ITEMS_SearchItemCodeTable(pUnit, (int32_t)pItem, pItemTxt->dwLen);
    if ((int)nItemDuration <= 0) {
      return 0;
    }

    SkillsServer::D2UpdateState(pUnit, eState, 0);
    int nPrevBuffFrames = 0;
    D2StatListExStrc* pStatList = D2Common::Stats::StatsEx::GetStatsByState(pUnit, eState);
    if (pStatList) {
      D2StatListExStrc* pStatListExpireFrame;
      pStatListExpireFrame = (D2StatListExStrc*)D2Common::Stats::StatsEx::STATLIST_GetFullListPtr(pStatList);
      nPrevBuffFrames = (int)pStatListExpireFrame - pGame->dwGameFrame;
    }

    int nStatValue = pGame->dwGameFrame + nPrevBuffFrames + nItemDuration;
    if (!pStatList) {
      if (!pUnit) {
        nUnitGUID = -1;
        eUnitType = UNIT_COUNT;
      } else {
        nUnitGUID = pUnit->nUnitGUID;
        eUnitType = pUnit->eUnitType;
      }

      pStatList = (D2StatListExStrc*)D2Common::Stats::StatsEx::AllocStatList(pGame->pMemoryPool, 2, 0, eUnitType, nUnitGUID);
      if (!pStatList) {
        return 0;
      }

      D2Common::Stats::StatsEx::SetState(pStatList, eState);
      D2Common::DATATBLS::ItemStats::SetState(pUnit, eState, 1);
      D2Common::Stats::StatsEx::STATLIST_SetExpireFunction(pStatList, SkillsServer::DefaultExpireFunction);
      D2Common::Stats::StatsEx::STATLIST_AttachStatListToUnit(pUnit, pStatList, 1);
    }
    if (nStatValue) {
      D2Common::Stats::StatsEx::STATSEX_SetStatListTimeout(pStatList, nStatValue);
      GAME::Event::SetEvent(pGame, pUnit, 0xc, nStatValue, 0, 0);
    }

    int* pCalcPtr = &pItemTxt->dwCalc1;
    short int* pStatIdPtr = &pItemTxt->wStat1;
    nPrevBuffFrames = 3;
    do {
      eUnitStat = (eD2UnitStat)*pStatIdPtr;
      if ((int)eUnitStat >= 0 && (int)eUnitStat < sgptDataTable->nTxtItemStatCostSize) {
        pStatCost = D2Client::GAME::SCmd::TXT_ItemStatCost_GetLine(eUnitStat);
        if (pStatCost) {
          nItemDuration = D2Common::ITEMS::Items::ITEMS_SearchItemCodeTable(pUnit, (int32_t)pItem, *pCalcPtr);
          if (nItemDuration) {
            D2Common::Stats::StatsEx::D2AddStatToStatsListEx(pStatList, eUnitStat, nItemDuration, 0);
            if (eUnitStat == UNITSTAT_staminarecoverybonus && (int)nItemDuration > 0) {
              nStatValue = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_maxstamina, 0);
              nCurrentStamina = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_stamina, 0);
              if (nCurrentStamina < nStatValue) {
                D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit, UNITSTAT_stamina, nStatValue + 0x100, 0);
              }
            }
          }
        }
      }

      pCalcPtr++;
      pStatIdPtr++;
      nPrevBuffFrames--;
    } while (nPrevBuffFrames);

    return 1;
}

// Clears then reapplies timed buff states associated with an item (e.g. charged/triggered skill effects). Iterates wCState1/wCState2 from the item's ItemsTxt row: for each valid state, removes the existing statlist and clears the state on the unit, then calls ITEM_ApplyTimedBuffStats to reapply. Returns non-zero if any buff was applied.
BOOL __fastcall ITEM_RefreshBuffStates(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pItem, D2UnitStrc * pTarget, int nX, int nY, eD2Skills eSkill) {
    uint32_t nItemClassId;
    D2StatListExStrc* pStatList;
    eD2States eStateCheck;
    if (!pItem) {
      nItemClassId = -1;
    } else {
      nItemClassId = pItem->nClassId;
    }

    D2ItemsTxt* pItemTxt = D2Common::DATATBLS::ItemTbls::TXT_Items_GetLine(nItemClassId);
    if (!pItemTxt) {
      return 0;
    }

    BOOL bRefreshApplied = 0;
    short int* pClearStatePtr = &pItemTxt->wCState1;
    int nClearStatesLeft = 2;
    do {
      eD2States eState;
      eState = (eD2States)*pClearStatePtr;
      if ((int)eState > 0 && (int)eState < sgptDataTable->nTxtStatesSize) {
        pStatList = D2Common::Stats::StatsEx::GetStatsByState(pUnit, eState);
        if (pStatList) {
          D2Common::Stats::StatsEx::STATLIST_RemoveAndRecalc(pUnit, pStatList);
          D2Common::Stats::StatsEx::FreeStatList(&pStatList->sStatList);
        }

        eStateCheck = D2Common::DATATBLS::ItemStats::UNIT_GetUnitState(pUnit, eState);
        if (eStateCheck != STATE_none) {
          D2Common::DATATBLS::ItemStats::SetState(pUnit, eState, 0);
        }

        bRefreshApplied = 1;
      }

      pClearStatePtr++;
      nClearStatesLeft--;
    } while (nClearStatesLeft);

    BOOL bApplied = ITEM_ApplyTimedBuffStats(pGame, pUnit, pItem, pTarget, nX, nY, eSkill);
    if (!bApplied) {
      return bRefreshApplied;
    }

    bRefreshApplied = 1;
    return bRefreshApplied;
}

BOOL __fastcall SKILLITEM_ApplyRejuvenationPotionEffect(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pItem, D2UnitStrc * pTarget, int nX, int nY, eD2Skills eSkill) {
    eD2UnitStat eUnitStat = D2Common::ITEMS::Items::ITEM_GetItemData_nFileIndex(pItem);
    if (!((int)eUnitStat >= 0 && (int)eUnitStat < sgptDataTable->nTxtItemStatCostSize)) {
      return 0;
    }

    int nValue = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pItem, UNITSTAT_value, 0);
    if (nValue) {
      D2Common::Stats::StatsEx::STATLIST_AddUnitStat(pUnit, eUnitStat, nValue, 0);
      return 1;
    }

    return 0;
}

// Handles the Personalize item spell (Ear/Charsi imbue interaction). Verifies pUnit is a player, checks if they are trading with an Inscriber object (classId 0x10B). If so, clears interact info and sends TradeAction 0x11. Sets interact info to mode 4 with the target item GUID, then sends TradeAction 0x15 and calls ITEMMODE_CheckItemLevel.
// @sourcefile .\SKILLS\SkillItem.cpp
BOOL __fastcall SKILLITEM_PersonalizeItemSpell(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pItem, D2UnitStrc * pTarget, int nX, int nY, eD2Skills eSkill) {
    D2ClientStrc* pClient;
    int32_t nInteractGUID;
    if (!(pUnit && pUnit->eUnitType == UNIT_PLAYER)) {
      return 0;
    }

    BOOL bIsBusy = PLAYER::Player::GetPlayerTradeTickOrBusy(pUnit);
    if (bIsBusy) {
      D2UnitStrc* pNpc;
      pNpc = UNIT::SUnit::GetInteractedNpc(pGame, pUnit);
      if (!pNpc) {
        return 0;
      }
      if (pNpc->eUnitType != UNIT_OBJECT) {
        return 0;
      }
      if (pNpc->nClassId != 0x10b) {
        return 0;
      }

      UNIT::SUnit::ClearInteractInfo(pUnit);
      ITEMS::ItemMode::ITEMMODE_CheckItemLevel(pGame, pUnit);
      pClient = UNIT::SUnit::SUNIT_GetClient(pUnit, ".\\SKILLS\\SkillItem.cpp", 0x3b3);
      GAME::SCmd::NET_D2GS_SERVER_Send_0x77_TRADEREQUEST(pClient, 0x11);
    }
    if (!pItem) {
      nInteractGUID = -1;
    } else {
      nInteractGUID = pItem->nUnitGUID;
    }

    UNIT::SUnit::SetInteractInfo(pUnit, UNIT_ITEM, nInteractGUID);
    pClient = UNIT::SUnit::SUNIT_GetClient(pUnit, ".\\SKILLS\\SkillItem.cpp", 0x3c1);
    GAME::SCmd::NET_D2GS_SERVER_Send_0x77_TRADEREQUEST(pClient, 0x15);
    ITEMS::ItemMode::ITEMMODE_CheckItemLevel(pGame, pUnit);
    return 0;
}

