    D2UnitStrc* pAttacker = pUnit;
    if (!(pUnit && pTarget && pTarget->eUnitFlags >> 2 & 1)) {
      return 0;
    }

    int32_t nMinDmg = D2Common::Stats::StatsEx::ITEM_GetMinimalStatValueShifted(pUnit, eSkill >> 0x10, eSkill);
